import React from "react";
import { AbsoluteFill, interpolate, useCurrentFrame, spring, useVideoConfig } from "remotion";
import { VisibleMovingDots } from "../components/MovingDots";
import { GradientBorder } from "../components/GradientBorder";
import { PlugAndPlayBar } from "../components/PlugAndPlayBar";
import { colors, plugAndPlayBarHeight } from "../styles";

interface SetupSceneProps {
  extensionName: string;
  extensionCommand: string;
}

// V4 Setup Scene with TYPE: STDIO field and Extension Added animation
export const SetupScene: React.FC<SetupSceneProps> = ({
  extensionName,
  extensionCommand,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Modal animation - clean, no tilt
  const modalScale = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Typing animations
  const nameChars = Math.floor(
    interpolate(frame, [25, 25 + extensionName.length * 2.5], [0, extensionName.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const commandStart = 25 + extensionName.length * 2.5 + 15;
  const commandChars = Math.floor(
    interpolate(frame, [commandStart, commandStart + extensionCommand.length * 1.8], [0, extensionCommand.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const cursorBlink = Math.sin(frame * 0.4) > 0;
  const typingComplete = commandChars >= extensionCommand.length;

  // Extension Added animation
  const showExtensionAdded = frame > 200;
  const extensionAddedScale = showExtensionAdded
    ? spring({
        frame: frame - 200,
        fps,
        config: { damping: 10, stiffness: 100 },
      })
    : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: colors.black }}>
      <GradientBorder>
        <AbsoluteFill style={{ backgroundColor: colors.black }}>
          {/* Moving dots */}
          <VisibleMovingDots />

          {/* Dimmed overlay */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: plugAndPlayBarHeight,
              backgroundColor: "rgba(0, 0, 0, 0.1)",
            }}
          />

          {/* Modal */}
          <AbsoluteFill
            style={{
              paddingBottom: plugAndPlayBarHeight,
              justifyContent: "center",
              alignItems: "center",
              padding: 20,
            }}
          >
            <div
              style={{
                width: "95%",
                backgroundColor: colors.white,
                borderRadius: 28,
                padding: 44,
                transform: `scale(${modalScale})`,
                boxShadow: "0 25px 70px rgba(0, 0, 0, 0.5)",
              }}
            >
              {/* Header */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 16,
                  marginBottom: 36,
                  paddingBottom: 24,
                  borderBottom: "3px solid #E8E8E8",
                }}
              >
                <div
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 14,
                    backgroundColor: colors.teal,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <svg width="30" height="30" viewBox="0 0 24 24" fill="white">
                    <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z" />
                  </svg>
                </div>
                <span
                  style={{
                    fontSize: 36,
                    fontWeight: 700,
                    color: colors.black,
                    fontFamily: "'Inter', sans-serif",
                  }}
                >
                  Add Extension
                </span>
              </div>

              {/* Form */}
              <div style={{ display: "flex", flexDirection: "column", gap: 28 }}>
                {/* Extension Name */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Extension Name
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#F5F5F5",
                      borderRadius: 12,
                      border: "2px solid #E0E0E0",
                      fontSize: 28,
                      fontFamily: "'Inter', sans-serif",
                      color: colors.black,
                      minHeight: 34,
                    }}
                  >
                    {extensionName.slice(0, nameChars)}
                    {nameChars < extensionName.length && nameChars > 0 && cursorBlink && (
                      <span style={{ color: colors.teal }}>|</span>
                    )}
                  </div>
                </div>

                {/* Command */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Command
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#1a1a1a",
                      borderRadius: 12,
                      border: "2px solid #333",
                      fontSize: 24,
                      fontFamily: "'SF Mono', 'Fira Code', monospace",
                      color: colors.teal,
                      minHeight: 34,
                      wordBreak: "break-all",
                    }}
                  >
                    {extensionCommand.slice(0, commandChars)}
                    {commandChars < extensionCommand.length && commandChars > 0 && cursorBlink && (
                      <span style={{ color: colors.orange }}>|</span>
                    )}
                  </div>
                </div>

                {/* Type - STDIO */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Type
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#F5F5F5",
                      borderRadius: 12,
                      border: "2px solid #E0E0E0",
                      fontSize: 24,
                      fontFamily: "'Inter', sans-serif",
                      color: colors.black,
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <span>STDIO</span>
                    <svg width="28" height="28" viewBox="0 0 24 24" fill="#666">
                      <path d="M7 10l5 5 5-5z" />
                    </svg>
                  </div>
                </div>
              </div>

              {/* Save button */}
              <div style={{ marginTop: 36, display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 20 }}>
                {/* Extension Added message */}
                {showExtensionAdded && (
                  <div
                    style={{
                      transform: `scale(${extensionAddedScale})`,
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                    }}
                  >
                    <svg width="34" height="34" viewBox="0 0 24 24" fill={colors.teal}>
                      <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" />
                    </svg>
                    <span
                      style={{
                        fontSize: 26,
                        color: colors.teal,
                        fontFamily: "'Inter', sans-serif",
                        fontWeight: 600,
                      }}
                    >
                      Extension Added!
                    </span>
                  </div>
                )}

                <div
                  style={{
                    padding: "16px 40px",
                    backgroundColor: typingComplete ? colors.teal : "#ccc",
                    borderRadius: 12,
                    fontSize: 24,
                    fontWeight: 600,
                    color: colors.white,
                    fontFamily: "'Inter', sans-serif",
                    boxShadow: typingComplete ? `0 6px 24px rgba(78, 205, 196, 0.4)` : "none",
                  }}
                >
                  Save Changes
                </div>
              </div>
            </div>
          </AbsoluteFill>

          {/* Teal bar */}
          <PlugAndPlayBar />
        </AbsoluteFill>
      </GradientBorder>
    </AbsoluteFill>
  );
};

// src/template/sequences/SetupRouter.tsx
import React from "react";

import type { SetupConfig } from "../config";

// Your existing setup scenes:
import { SetupScene } from "./SetupScene";
import { SetupSceneBuiltIn } from "./SetupSceneBuiltIn";
import { SetupSceneHTTP } from "./SetupSceneHTTP";
import { SetupSceneHTTPWithHeaders } from "./SetupSceneHTTPWithHeaders";
import { SetupSceneSTDIOWithEnv } from "./SetupSceneSTDIOWithEnv";

export const SetupRouter: React.FC<{ setup: SetupConfig }> = ({ setup }) => {
  switch (setup.type) {
    case "builtin":
      return <SetupSceneBuiltIn extensionName={setup.extensionName} extensionDescription={setup.extensionDescription} />;

    case "stdio":
      return (
        <SetupScene
          extensionName={setup.extensionName}
          extensionCommand={setup.extensionCommand}
        />
      );

    case "stdio_with_env":
      return (
        <SetupSceneSTDIOWithEnv
          extensionName={setup.extensionName}
          extensionCommand={setup.extensionCommand}
          envVars={setup.envVars}
        />
      );

    case "http":
      return <SetupSceneHTTP extensionName={setup.extensionName} endpoint={setup.endpoint} />;

    case "http_with_headers":
      return (
        <SetupSceneHTTPWithHeaders
        extensionName={setup.extensionName}
        endpoint={setup.endpoint}
        requestHeaders={setup.requestHeaders}
        />
      );

    default: {
      // Exhaustiveness check (TypeScript will error if a case is missing)
      const _never: never = setup;
      return null;
    }
  }
};

import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from "remotion";
import { colors, plugAndPlayBarHeight } from "../styles";
import { VisibleMovingDots } from "../components/MovingDots";
import { PlugAndPlayBar } from "../components/PlugAndPlayBar";

interface SetupSceneBuiltInProps {
  extensionName?: string;
  extensionDescription?: string;
}

export const SetupSceneBuiltIn: React.FC<SetupSceneBuiltInProps> = ({
  extensionName = "Developer",
  extensionDescription = "General development tools useful for software engineering.",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation timing
  const modalAppearFrame = 15;
  const toggleStartFrame = 60;
  const toggleCompleteFrame = 90;
  const successFrame = 120;

  // Modal scale animation
  const modalScale = spring({
    frame: frame - modalAppearFrame,
    fps,
    config: {
      damping: 15,
      stiffness: 150,
      mass: 0.8,
    },
  });

  const modalOpacity = interpolate(
    frame,
    [modalAppearFrame, modalAppearFrame + 10],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  // Toggle animation
  const toggleProgress = interpolate(
    frame,
    [toggleStartFrame, toggleCompleteFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.4, 0, 0.2, 1) }
  );

  // Success checkmark animation
  const successScale = spring({
    frame: frame - successFrame,
    fps,
    config: {
      damping: 12,
      stiffness: 200,
      mass: 0.5,
    },
  });

  const successOpacity = interpolate(
    frame,
    [successFrame, successFrame + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Glow pulse for success
  const glowPulse = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.6, 1],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: colors.background,
      }}
    >
      {/* Moving dots background */}
      <VisibleMovingDots />

      {/* Dark overlay for better contrast - leave space for PlugAndPlayBar */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: plugAndPlayBarHeight,
          backgroundColor: "rgba(0, 0, 0, 0.1)",
        }}
      />

      {/* Modal */}
      {frame >= modalAppearFrame && (
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            padding: 20,
            paddingBottom: plugAndPlayBarHeight + 20,
          }}
        >
          <div
            style={{
              width: "95%",
              backgroundColor: "#1a1a1a",
              borderRadius: 28,
              padding: 56,
              transform: `scale(${modalScale})`,
              opacity: modalOpacity,
              boxShadow: frame >= successFrame && toggleProgress >= 1
                ? `0 0 ${60 * glowPulse}px ${colors.teal}40, 0 0 ${120 * glowPulse}px ${colors.teal}20`
                : "0 25px 70px rgba(0, 0, 0, 0.5)",
              border: `1px solid ${frame >= successFrame && toggleProgress >= 1 ? colors.teal : "#333"}`,
              transition: "border-color 0.3s ease",
            }}
          >
            {/* Header */}
            <div
              style={{
                fontSize: 48,
                fontWeight: 700,
                color: "white",
                marginBottom: 16,
                fontFamily: "SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif",
              }}
            >
              Built-in Extension
            </div>
            <div
              style={{
                fontSize: 28,
                color: "#888",
                marginBottom: 56,
                fontFamily: "SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif",
              }}
            >
              Enable this extension with one click
            </div>

            {/* Extension Card */}
            <div
              style={{
                backgroundColor: "#252525",
                borderRadius: 20,
                padding: 44,
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                border: `1px solid ${toggleProgress >= 1 ? colors.teal : "#333"}`,
                transition: "border-color 0.3s ease",
              }}
            >
              {/* Left side - Extension info */}
              <div style={{ flex: 1, marginRight: 36 }}>
                <div
                  style={{
                    fontSize: 38,
                    fontWeight: 600,
                    color: "white",
                    marginBottom: 16,
                    fontFamily: "SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  {extensionName}
                </div>
                <div
                  style={{
                    fontSize: 26,
                    color: "#999",
                    lineHeight: 1.4,
                    fontFamily: "SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  {extensionDescription}
                </div>
              </div>

              {/* Right side - Toggle */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 18,
                }}
              >
                {/* Settings gear icon */}
                <div
                  style={{
                    width: 48,
                    height: 48,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    opacity: 0.5,
                  }}
                >
                  <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#888" strokeWidth="2">
                    <circle cx="12" cy="12" r="3" />
                    <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
                  </svg>
                </div>

                {/* Toggle Switch */}
                <div
                  style={{
                    width: 96,
                    height: 52,
                    backgroundColor: interpolate(toggleProgress, [0, 1], [0, 1]) > 0.5 ? colors.teal : "#444",
                    borderRadius: 26,
                    padding: 4,
                    cursor: "pointer",
                    transition: "background-color 0.3s ease",
                    position: "relative",
                  }}
                >
                  {/* Toggle knob */}
                  <div
                    style={{
                      width: 44,
                      height: 44,
                      backgroundColor: "white",
                      borderRadius: "50%",
                      transform: `translateX(${interpolate(toggleProgress, [0, 1], [0, 44])}px)`,
                      boxShadow: "0 2px 8px rgba(0, 0, 0, 0.3)",
                    }}
                  />
                </div>
              </div>
            </div>

            {/* Success Message */}
            {frame >= successFrame && (
              <div
                style={{
                  marginTop: 48,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 18,
                  opacity: successOpacity,
                  transform: `scale(${successScale})`,
                }}
              >
                {/* Checkmark circle */}
                <div
                  style={{
                    width: 60,
                    height: 60,
                    backgroundColor: colors.teal,
                    borderRadius: "50%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="20 6 9 17 4 12" />
                  </svg>
                </div>
                <div
                  style={{
                    fontSize: 34,
                    fontWeight: 600,
                    color: colors.teal,
                    fontFamily: "SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  Extension Enabled!
                </div>
              </div>
            )}
          </div>
        </AbsoluteFill>
      )}

      {/* Plug and Play Bar */}
      <PlugAndPlayBar />
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";
import { VisibleMovingDots } from "../components/MovingDots";
import { GradientBorder } from "../components/GradientBorder";
import { PlugAndPlayBar } from "../components/PlugAndPlayBar";
import { colors, plugAndPlayBarHeight } from "../styles";

interface SetupSceneHTTPProps {
  extensionName: string;
  endpoint: string; // ✅ matches config.setup.endpoint
}

// Setup Scene for HTTP/HTTPS extensions - shows Endpoint instead of Command, Type: HTTP
export const SetupSceneHTTP: React.FC<SetupSceneHTTPProps> = ({
  extensionName,
  endpoint,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Modal animation - clean, no tilt
  const modalScale = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Typing animations
  const nameChars = Math.floor(
    interpolate(
      frame,
      [25, 25 + extensionName.length * 2.5],
      [0, extensionName.length],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );

  const endpointStart = 25 + extensionName.length * 2.5 + 15;
  const endpointChars = Math.floor(
    interpolate(
      frame,
      [endpointStart, endpointStart + endpoint.length * 1.8],
      [0, endpoint.length],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );

  const cursorBlink = Math.sin(frame * 0.4) > 0;
  const typingComplete = endpointChars >= endpoint.length;

  // ✅ Make "Extension Added!" appear after typing finishes (not a fixed frame)
  const endpointTypingDone = endpointStart + endpoint.length * 1.8;
  const extensionAddedDelay = Math.ceil(endpointTypingDone + 30);

  const showExtensionAdded = frame > extensionAddedDelay;
  const extensionAddedScale = showExtensionAdded
    ? spring({
        frame: frame - extensionAddedDelay,
        fps,
        config: { damping: 10, stiffness: 100 },
      })
    : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: colors.black }}>
      <GradientBorder>
        <AbsoluteFill style={{ backgroundColor: colors.black }}>
          {/* Moving dots */}
          <VisibleMovingDots />

          {/* Dimmed overlay */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: plugAndPlayBarHeight,
              backgroundColor: "rgba(0, 0, 0, 0.1)",
            }}
          />

          {/* Modal */}
          <AbsoluteFill
            style={{
              paddingBottom: plugAndPlayBarHeight,
              justifyContent: "center",
              alignItems: "center",
              padding: 20,
            }}
          >
            <div
              style={{
                width: "95%",
                backgroundColor: colors.white,
                borderRadius: 28,
                padding: 44,
                transform: `scale(${modalScale})`,
                boxShadow: "0 25px 70px rgba(0, 0, 0, 0.5)",
              }}
            >
              {/* Header */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 16,
                  marginBottom: 36,
                  paddingBottom: 24,
                  borderBottom: "3px solid #E8E8E8",
                }}
              >
                <div
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 14,
                    backgroundColor: colors.teal,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <svg width="30" height="30" viewBox="0 0 24 24" fill="white">
                    <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z" />
                  </svg>
                </div>
                <span
                  style={{
                    fontSize: 36,
                    fontWeight: 700,
                    color: colors.black,
                    fontFamily: "'Inter', sans-serif",
                  }}
                >
                  Add Extension
                </span>
              </div>

              {/* Form */}
              <div style={{ display: "flex", flexDirection: "column", gap: 28 }}>
                {/* Extension Name */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Extension Name
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#F5F5F5",
                      borderRadius: 12,
                      border: "2px solid #E0E0E0",
                      fontSize: 28,
                      fontFamily: "'Inter', sans-serif",
                      color: colors.black,
                      minHeight: 34,
                    }}
                  >
                    {extensionName.slice(0, nameChars)}
                    {nameChars < extensionName.length &&
                      nameChars > 0 &&
                      cursorBlink && <span style={{ color: colors.teal }}>|</span>}
                  </div>
                </div>

                {/* Endpoint */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Endpoint
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#1a1a1a",
                      borderRadius: 12,
                      border: "2px solid #333",
                      fontSize: 24,
                      fontFamily: "'SF Mono', 'Fira Code', monospace",
                      color: colors.teal,
                      minHeight: 34,
                      wordBreak: "break-all",
                    }}
                  >
                    {endpoint.slice(0, endpointChars)}
                    {endpointChars < endpoint.length &&
                      endpointChars > 0 &&
                      cursorBlink && <span style={{ color: colors.orange }}>|</span>}
                  </div>
                </div>

                {/* Type - HTTP */}
                <div>
                  <label
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      color: "#666",
                      marginBottom: 12,
                      display: "block",
                      fontFamily: "'Inter', sans-serif",
                    }}
                  >
                    Type
                  </label>
                  <div
                    style={{
                      padding: "18px 22px",
                      backgroundColor: "#F5F5F5",
                      borderRadius: 12,
                      border: "2px solid #E0E0E0",
                      fontSize: 24,
                      fontFamily: "'Inter', sans-serif",
                      color: colors.black,
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <span>HTTP</span>
                    <svg width="28" height="28" viewBox="0 0 24 24" fill="#666">
                      <path d="M7 10l5 5 5-5z" />
                    </svg>
                  </div>
                </div>
              </div>

              {/* Save button */}
              <div
                style={{
                  marginTop: 36,
                  display: "flex",
                  justifyContent: "flex-end",
                  alignItems: "center",
                  gap: 20,
                }}
              >
                {/* Extension Added message */}
                {showExtensionAdded && (
                  <div
                    style={{
                      transform: `scale(${extensionAddedScale})`,
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                    }}
                  >
                    <svg width="34" height="34" viewBox="0 0 24 24" fill={colors.teal}>
                      <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" />
                    </svg>
                    <span
                      style={{
                        fontSize: 26,
                        color: colors.teal,
                        fontFamily: "'Inter', sans-serif",
